/**
 * Safety hints (MCP tool annotations) of every tool — the one place that says what a tool may do to the world, so an
 * approval policy reads a mechanism instead of guessing from names.
 *
 * The four hints follow the MCP definitions and are written for the worst thing a tool can do in any of its modes:
 *  - readOnly     — it changes nothing: no file written, no process started, no state of the project touched.
 *  - destructive  — it can delete or overwrite something that is not regenerated by the same call: a file at a path the
 *                   caller names, a setting, an installed encoder. Adding a new experiment, or replacing production
 *                   (the replaced model is backed up and `mloop_rollback` returns it) is not destructive.
 *  - idempotent   — the same call again has no further effect (a retry is safe).
 *  - openWorld    — it reaches beyond the local machine and project: a download, a listener other hosts can call.
 * A read-only tool says `destructiveHint: false`; the field is only meaningful otherwise, but a policy should not have to
 * know that. Where a tool has modes (`mloop_threshold` chooses or clears), the hint is the worst mode's.
 *
 * `hintsFor` throws for a tool without an entry, so a tool added to the server cannot ship unannotated.
 */

export interface ToolHints {
  readOnlyHint: boolean;
  destructiveHint: boolean;
  idempotentHint: boolean;
  openWorldHint: boolean;
}

const hints = (readOnlyHint: boolean, destructiveHint: boolean, idempotentHint: boolean, openWorldHint = false): ToolHints =>
  ({ readOnlyHint, destructiveHint, idempotentHint, openWorldHint });

/** Reads the project or a data file and writes nothing. */
const READS = hints(true, false, true);
/** Writes at a path the caller names or declares settings — a repeat gives the same result, and it can overwrite. */
const WRITES_OVER = hints(false, true, true);
/** Adds to the project (an experiment, an entry, a process) — a repeat adds again. */
const ADDS = hints(false, false, false);

export const TOOL_HINTS: Readonly<Record<string, ToolHints>> = {
  // Reads
  mloop_list: READS,
  mloop_status: READS,
  mloop_info: READS,
  mloop_analyze: READS,
  mloop_compare: READS,
  mloop_evaluate: READS,
  mloop_validate: READS,
  mloop_logs: READS,
  mloop_trigger: READS,
  mloop_drift: READS,
  mloop_embed: READS,
  mloop_explain: READS,
  mloop_project_overview: READS,
  mloop_token: READS, // issues a signed token; nothing is stored

  // Adds
  mloop_train: ADDS,        // a new experiment; a better model replaces production, the old one is backed up
  mloop_auto_train: ADDS,   // profiles, then trains
  mloop_quick_start: ADDS,  // init, train and promote in one call
  mloop_init: ADDS,         // a new project directory
  mloop_feedback: ADDS,     // `add` appends an entry
  mloop_rollback: ADDS,     // again returns to what production held before the rollback
  mloop_predict: hints(false, true, false), // `output` overwrites the named file; `log` appends to the prediction log
  mloop_serve: hints(false, false, false, true), // starts a server that keeps running and listens for other hosts

  // Replaces the production pointer with a backup, and repeats are no-ops
  mloop_promote: hints(false, false, true),

  // Writes beside the model or at a caller-named path; `clear` / `reset` / `remove` modes delete
  mloop_threshold: WRITES_OVER,
  mloop_calibrate: WRITES_OVER,
  mloop_export_onnx: WRITES_OVER,
  mloop_prep: WRITES_OVER,
  mloop_prep_plan: WRITES_OVER,
  mloop_features_select: WRITES_OVER,
  mloop_sample: WRITES_OVER,
  mloop_detect: WRITES_OVER, // writes only when `output` is given
  mloop_docker: WRITES_OVER, // writes a Dockerfile and a compose file over the ones there

  // Installs download weights or a runtime; remove deletes them
  mloop_encoder: hints(false, true, true, true),
  mloop_runtime: hints(false, true, true, true),
};

/** The hints of tool <paramref name="name"/>; throws when it has none. */
export function hintsFor(name: string): ToolHints {
  const found = TOOL_HINTS[name];
  if (!found)
    throw new Error(`Tool '${name}' has no safety hints: add it to TOOL_HINTS in src/tool-hints.ts.`);
  return found;
}
